scwin.fn_Init = function() {
    // 한달전 날짜 : 20081110: 허기영 요구사항
    var vCurDate = $c.ut.cGetToday("yyyymmdd");
    edt_SDATE.setValue($c.ut.cGetMinusDate2(vCurDate, 7)); // 일주일전 날짜
    edt_EDATE.setValue($c.ut.cGetToday("yyyymmdd")); // 현재날짜
    edt_FromDt.setValue($c.ut.cGetToday("yyyymmdd")); // 현재날짜
    edt_ToDt.setValue($c.ut.cGetToday("yyyymmdd")); // 현재날짜

    var h = "FROM_DT:string,TO_DT:string";

	//----W-Craft WebSquare 변환 확인: SetDataHeader----//
    dts_List.SetDataHeader(h);
    if (js_market != "9") {
        $c.stf.showObj(panel_mkt, false);
    }
};





/*최근호출일시 가져옴*/
scwin.fn_getRecentReqDT = function() {
    var url = "/listingCommon.do?method=listGeneralForDynamicName&outputMessageId=CODE_OUT" +
        //		var url = "/listingCommon.do?method=listGeneral&outputMessageId=CODE_OUT" +
        "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=lds.stf.ksd.isuregfact.select.recentreqddtm.dyn";
    dts_RecentReqDT.DataID = encodeURI(url);

	//----W-Craft WebSquare 변환 확인: reset----//
    dts_RecentReqDT.reset();
};


/*익일영업일 가져옴*/
