    dts_getDate.DataID = encodeURI(url);

	//----W-Craft WebSquare 변환 확인: reset----//
    dts_getDate.reset();
};


/*시장조치 내용 불러오기*/
scwin.fn_getMktReq = function() {
    if (!scwin.fn_restrictDuration()) return;
    var res = window.confirm("예탁원 발행정보을 요청하시겠습니까?");
    if (res) {
        var url = "/MktVerifSystem.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=recvKsdIsuRegFactReq";
        url += "&FROM_DT=" + $c.stf.getObjectValue(edt_FromDt);
        url += "&TO_DT=" + $c.stf.getObjectValue(edt_ToDt);
        dts_List.DataID = encodeURI(url);

	//----W-Craft WebSquare 변환 확인: Reset----//
        dts_List.Reset();
        $c.cm.ShowWin(grd_Grid);
    }
};
scwin.fn_listNewPassword = function() {
    var argv = fn_listNewPassword.arguments;
    var argc = fn_listNewPassword.arguments.length;
    scwin.vPAGENO = (argc == 0) ? 0 : scwin.vPAGENO = argv[0];
    $c.cm.ShowWin(grd_Grid);
    var lPageNo = 0;
    if (scwin.vPAGENO == 0) {
        lPageNo = 1;
    } else {
        lPageNo = scwin.vPAGENO;
    }
    var secuGrpId = "";
    if ($c.stf.getObjectValue(chb_Grp_ST_21) == 'Y') secuGrpId += '21,';
    if ($c.stf.getObjectValue(chb_Grp_DR_51) == 'Y') secuGrpId += '51,';
    if ($c.stf.getObjectValue(chb_Grp_SR_22) == 'Y') secuGrpId += '22,';
    if ($c.stf.getObjectValue(chb_Grp_SW_23) == 'Y') secuGrpId += '23,';
    if ($c.stf.getObjectValue(chb_Grp_BC_31) == 'Y') secuGrpId += 'BC,';
    if ($c.stf.getObjectValue(chb_Grp_BND_11) == 'Y') secuGrpId += '11,';
    if ($c.stf.getObjectValue(chb_Grp_EF_31) == 'Y') secuGrpId += 'EF,';
    if ($c.stf.getObjectValue(chb_Grp_EN_44) == 'Y') secuGrpId += '44,';
    if ($c.stf.getObjectValue(chb_Grp_EW_42) == 'Y') secuGrpId += '42,';
    if ($c.stf.getObjectValue(chb_Grp_EW_42) == 'Y') secuGrpId += '42,';
    if ($c.stf.getObjectValue(chb_Grp_IC_61) == 'Y') secuGrpId += '61,';
    if ($c.stf.getObjectValue(chb_Grp_TC_32) == 'Y') secuGrpId += '32,';
    if ($c.stf.getObjectValue(chb_Grp_PF_31) == 'Y') secuGrpId += 'PF,';
    if ($c.stf.getObjectValue(chb_Grp_All) == 'Y') secuGrpId = '';
    //alert("vPAGENO="+vPAGENO);
    //alert("lPageNo="+lPageNo);
    //alert("lPageSize="+getObjectValue(cmb_PerPage));

    var url = "/listingCommon.do?method=listGeneralForDynamicName&outputMessageId=KSD_ISUREGFACT_INOUT&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&SCREN_ID=" + scwin.vScrenID + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=lds.stf.ksd.isuregfact.select.list.dyn";
    url += "&{P}V_ISU_KOR_NM=" + $c.stf.getObjectValue(txb_ISUR_NM);
    url += "&{P}V_SECUGRP_ID=" + secuGrpId;
    url += "&{P}V_SPOT_ISU_TRD_MKT_TP_CD=" + $c.stf.getObjectValue(rdo_SPOT_ISU_TRD_MKT_TP_CD);
    url += "&{P}V_KSD_ISU_ERAS_TP_CD=" + $c.stf.getObjectValue(cmb_KSD_ISU_ERAS_TP_CD);
    url += "&{P}V_SDATE=" + $c.stf.getObjectValue(edt_SDATE);
    url += "&{P}V_EDATE=" + $c.stf.getObjectValue(edt_EDATE);
    url += "&{P}V_lPageNo=" + lPageNo;
    url += "&{P}V_lPageSize=" + $c.stf.getObjectValue(cmb_PerPage);
    //alert(url);
    dts_PassList.DataID = encodeURI(url);

	//----W-Craft WebSquare 변환 확인: Reset----//
    dts_PassList.Reset();
};
scwin.PageNoCall = function(vPageNo) {
    scwin.vCurrPageNo = vPageNo;
