scwin.fn_SetCode = function() {
    chb_Grp_All.setValue(1);
    scwin.fn_allCheck();
    $c.stf.Combo_CBDataSet(cmb_PerPage);
    //setObjectValue(cmb_APPL_RSLT, "R");

    dts_CORP_USR_TP_CD.DataID = "/CodeAction.do?method=listCodeValueName&inputMessageId=CODEVALUE_INOUT&outputMessageId=CODE_OUT&FOR=R&CD_ENG_NM=KSD_ISU_ERAS_TP_CD";

	//----W-Craft WebSquare 변환 확인: Reset----//
    dts_CORP_USR_TP_CD.Reset();

    // 신청구분코드 셋팅
    //dts_ApplRsltCd.DataID = "/CodeAction.do?method=listCodeValueName&inputMessageId=CODEVALUE_INOUT&outputMessageId=CODE_OUT"+
    //					"&FOR=R&CD_ENG_NM=APPL_RSLT_CD" ;
    //dts_ApplRsltCd.Reset();	

};
scwin.fn_readNewPassword = async function(row, colid) {
    if (colid == "INTEG_USR_ID") {
        //var vINTEG_USR_ID = dts_PassList.NameString(row, "INTEG_USR_ID");
        var vINTEG_USR_ID = dts_PassList.getCellData(row, "CORP_USR_REG_APPL_SEQ"); // SEQ
        //alert(vINTEG_USR_ID);

	//----W-Craft WebSquare 변환 확인: CreateDialogFrame----//
        await $c.frame.CreateDialogFrame("NEWPASS_READ|INTEG_USR_ID=" + vINTEG_USR_ID, "/issueinfo/ULDSTF30701.gfm", "비밀번호 신규조회", 10, 10, 580, 800, "window");
    } else if (colid == "COM_NM") {
        scwin.gIsurCd = dts_PassList.getCellData(row, "ISUR_CD");
        $c.stf.fn_PopupCorpInfo();
    }
};
scwin.fn_allCheck = function() {
    var checkArray = [chb_Grp_ST_21, chb_Grp_DR_51, chb_Grp_SR_22, chb_Grp_SW_23, chb_Grp_BC_31, chb_Grp_BND_11, chb_Grp_EF_31, chb_Grp_EN_44, chb_Grp_EW_42, chb_Grp_IC_61, chb_Grp_TC_32, chb_Grp_PF_31];
    if (chb_Grp_All.checked == true) {
        for (var i = 0; i < checkArray.length; i++) {
            checkArray[i].checked = 0;
        }
    }
};




/*예탁원 정보 수신된 내용이 있는지 체크*/
scwin.fn_btncnt = function() {
    var url = "/listingCommon.do?method=listGeneralForDynamicName&outputMessageId=MKTVERIFSYS_CNT_INOUT" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=lds.stf.ksd.isuregfact.select.regdd.cnt.regcondition" +
        //"&{P}V_REG_DD=" + reqKsdIsuRegDD ;
        "&{P}V_REG_DD=" + $c.stf.getObjectValue(edt_FromDt);
    dts_btnCnt.DataID = encodeURI(url);

	//----W-Craft WebSquare 변환 확인: reset----//
    dts_btnCnt.reset();
};
scwin.fn_restrictDuration = function() {
    var duration = 6;
    var start = $c.stf.getObjectValue(edt_FromDt);
    var end = $c.stf.getObjectValue(edt_ToDt);
    var startDate = new Date();
    var endDate = new Date();
    startDate.setYear(start.substring(0, 4));
    startDate.setMonth(start.substring(4, 6));
    startDate.setDate(start.substring(6, 8));
    endDate.setYear(end.substring(0, 4));
    endDate.setMonth(end.substring(4, 6));
    endDate.setDate(end.substring(6, 8));
    var diffTime = endDate.getTime() - startDate.getTime();
    var diffDays = diffTime / (1000 * 60 * 60 * 24);
    if (diffDays > duration) {
        var msg = " 조회기간은 7일 이하로 제한됩니다.";
        alert(msg);
        return false;
    }
    return true;
};
