scwin.dts_CORP_USR_TP_CD_OnLoadCompleted = function(e) {
    //채권상장신청자 제거
    for (var i = 1; i <= dts_CORP_USR_TP_CD.getTotalRow(); i++) {
        if (dts_CORP_USR_TP_CD.getCellData(i, "VALUE") == "71") {
